DO $$
DECLARE
  payload_count integer;
  duplicate_refs integer;
  missing_coords integer;
BEGIN
  SELECT jsonb_array_length(data) INTO payload_count FROM _mapa_catalogue_payload;
  IF payload_count <> 791 THEN
    RAISE EXCEPTION 'Catalogue payload row count mismatch: expected 791, got %', payload_count;
  END IF;
  SELECT count(*) INTO duplicate_refs
  FROM (
    SELECT x.source_ref
    FROM _mapa_catalogue_payload src
    CROSS JOIN LATERAL jsonb_to_recordset(src.data) AS x(source_ref text)
    GROUP BY x.source_ref HAVING count(*) > 1
  ) d;
  IF duplicate_refs <> 0 THEN
    RAISE EXCEPTION 'Catalogue contains % duplicate source_ref values', duplicate_refs;
  END IF;
  SELECT count(*) INTO missing_coords
  FROM _mapa_catalogue_payload src
  CROSS JOIN LATERAL jsonb_to_recordset(src.data) AS x(latitude double precision, longitude double precision)
  WHERE x.latitude IS NULL OR x.longitude IS NULL
     OR x.latitude NOT BETWEEN -90 AND 90
     OR x.longitude NOT BETWEEN -180 AND 180;
  IF missing_coords <> 0 THEN
    RAISE EXCEPTION 'Catalogue contains % missing or invalid coordinate pairs', missing_coords;
  END IF;
END;
$$;

INSERT INTO public.establishments (
  province_id, municipality_id, category_id,
  name, normalized_name, subtype, address,
  latitude, longitude, location_precision, location_source,
  source_ref, status
)
SELECT
  p.id,
  m.id,
  c.id,
  x.name,
  lower(trim(x.name)),
  x.subtype,
  x.address,
  x.latitude,
  x.longitude,
  x.location_precision,
  x.location_source,
  x.source_ref,
  x.status
FROM _mapa_catalogue_payload src
CROSS JOIN LATERAL jsonb_to_recordset(src.data) AS x(
  source_ref text, name text, category text, subtype text,
  municipality text, address text, latitude double precision,
  longitude double precision, location_precision text,
  location_source text, province text, status text
)
JOIN public.provinces p ON p.code = '18'
JOIN public.municipalities m
  ON m.province_id = p.id
 AND m.normalized_name = (
   CASE x.municipality
     WHEN 'Agrón' THEN 'agron'
